// JSON metnini dönüştürmek için kullanılır
import 'dart:convert';
// Vazife modelini projeye ekler
import '../../models/habit.dart';
// Structured pact proposal generated by the AI Guide.
// Ahit oluşturmak için kullanıcının açık onayını gerektirir
// AI önerisinden alınan ahit ayrıntılarını tutar
class PactSuggestion {
  // PactSuggestion nesnesinin başlangıç bilgilerini alır
  const PactSuggestion({
    // başlık parametresini zorunlu tutar
    required this.title,
    // description parametresini zorunlu tutar
    required this.description,
    // vazife ids parametresini zorunlu tutar
    required this.habitIds,
    // vazife names parametresini zorunlu tutar
    required this.habitNames,
    // target days parametresini zorunlu tutar
    required this.targetDays,
    // toplam days için isteğe bağlı başlangıç değeri alır
    this.totalDays = 7,
    // rationale için isteğe bağlı başlangıç değeri alır
    this.rationale = '',
  });
  // Başlık metnini tutar
  final String title;
  // Açıklama metnini tutar
  final String description;
  // Ahde bağlı vazifelerin ID listesini tutar
  final List<String> habitIds;
  // Ahde bağlanacak vazifelerin isimlerini tutar
  final List<String> habitNames;
  // Ahit için önerilen hedef gün sayısını tutar
  final int targetDays;
  // Ahit için önerilen toplam süreyi tutar
  final int totalDays;
  // AI önerisinin gerekçesini tutar
  final String rationale;
  // Nesnenin alanlarını JSONa uygun Map biçimine çevirir
  Map<String, dynamic> toJson() => {
        // Başlığı JSON alanına yazar
        'title': title,
        // Açıklamayı JSON alanına yazar
        'description': description,
        // Bağlı vazifelerin kimliklerini JSON alanına aktarır
        'habitIds': habitIds,
        // habitNames alanına gönderilecek değeri yerleştirir
        'habitNames': habitNames,
        // targetDays alanına gönderilecek değeri yerleştirir
        'targetDays': targetDays,
        // totalDays alanına gönderilecek değeri yerleştirir
        'totalDays': totalDays,
        // rationale alanına gönderilecek değeri yerleştirir
        'rationale': rationale,
      };
  // JSON alanlarını okuyarak yeni model nesnesi oluşturur
  factory PactSuggestion.fromJson(Map<String, dynamic> json) => PactSuggestion(
        // başlık alanına gelen değeri kullanır
        title: json['title'] as String? ?? 'Önerilen Ahit',
        // Vazifenin veya önerinin açıklamasını belirler
        description: json['description'] as String? ?? '',
        // Ahdin bağlı olduğu vazife IDlerini aktarır
        habitIds: (json['habitIds'] as List<dynamic>? ?? []).cast<String>(),
        // vazife names alanına gelen değeri kullanır
        habitNames: (json['habitNames'] as List<dynamic>? ?? []).cast<String>(),
        // target days alanına gelen değeri kullanır
        targetDays: (json['targetDays'] as num?)?.toInt() ?? 7,
        // toplam days alanına gelen değeri kullanır
        totalDays: (json['totalDays'] as num?)?.toInt() ?? 7,
        // Önerinin gerekçesini aktarır
        rationale: json['rationale'] as String? ?? '',
      );
  // AI yanıtı içinden geçerli ahit önerisi çıkarmayı dener
  // AI yanıtından geçerli ahit önerisi JSONunu ayıklar
  static PactSuggestion? tryExtract(String text, List<Habit> availableHabits) {
    // Hata oluşabilecek işlemleri denemeye başlar
    try {
      // Yanıtta pact_suggestion veya json kod bloğunu arar
      // regex bilgisini saklar
      final regex = RegExp(
          // JSON kod bloğunu bulacak düzenli ifadeyi tanımlar
          r'```(?:pact_suggestion|json)?\s*(\{[\s\S]*?\})\s*```',
          // Aramada büyük küçük harf duyarlılığını belirler
          caseSensitive: false);
      // match bilgisini saklar
      final match = regex.firstMatch(text);
      // JSON str bilgisini saklar
      String? jsonStr = match?.group(1);
      // Kod bloğu yoksa metindeki JSON benzeri bölümü arar
      // Gerekli veri yoksa alternatif işlem yolunu kullanır
      if (jsonStr == null) {
        // start idx için anahtar değer tablosu oluşturur
        final startIdx = text.indexOf('{');
        // end idx bilgisini saklar
        final endIdx = text.lastIndexOf('}');
        // Belirtilen koşul sağlanırsa bu işlemi uygular
        if (startIdx != -1 && endIdx > startIdx) {
          // candidate için güncel toplamı hesaplar
          final candidate = text.substring(startIdx, endIdx + 1);
          // Koleksiyonda aranan öğe bulunup bulunmadığını kontrol eder
          if (candidate.contains('pact_suggestion') ||
              // JSON adayında Türkçe ahit başlığı alanını arar
              candidate.contains('ahit_adi') ||
              // JSON adayında hedef gün alanını arar
              candidate.contains('target_days') ||
              // JSON adayında hedef gün alanını arar
              candidate.contains('targetDays')) {
            // JSON str bilgisini yeni değerle günceller
            jsonStr = candidate;
          }
        }
      }
      // Metinden JSON çıkarılamazsa öneri oluşturmaz
      if (jsonStr == null) return null;
      // Kaydedilen JSON metnini Dart verisine çevirir
      final decoded = jsonDecode(jsonStr);
      // Çözülen veri beklenen Map değilse işlemi durdurur
      if (decoded is! Map<String, dynamic>) return null;
      // data koşulunun doğru olup olmadığını bulur
      final data = decoded.containsKey('pact_suggestion')
          // Koşul doğruysa kullanılacak sonucu belirler
          ? (decoded['pact_suggestion'] as Map<String, dynamic>)
          // Koşul yanlışsa kullanılacak sonucu belirler
          : decoded;
      // Gelen veriden ahdin başlığını seçer
      final title =
          // Veriyi beklenen tipe dönüştürür
          (data['title'] ?? data['ahit_adi'] ?? data['name']) as String?;
      // Ahit başlığı boşsa öneriyi geçersiz sayar
      if (title == null || title.trim().isEmpty) return null;
      // Gelen veriden ahdin açıklamasını seçer
      final description =
          // Veriyi beklenen tipe dönüştürür
          (data['description'] ?? data['aciklama'] ?? '') as String;
      // Gelen veriden önerinin gerekçesini seçer
      final rationale = (data['rationale'] ?? data['gerekce'] ?? '') as String;
      // Önerinin hedef gün sayısını belirlemeye başlar
      final targetDays = ((data['target_days'] ??
              // Değer bulunmazsa varsayılan seçeneği kullanır
              data['targetDays'] ??
              // Değer bulunmazsa varsayılan seçeneği kullanır
              data['hedef_gun'] ??
              // Hedef gün alanını sayısal değere dönüştürür
              7) as num)
          // Hesaplanan sayıyı tam sayıya çevirir
          .toInt()
          // Sayıyı izin verilen alt ve üst sınırlarda tutar
          .clamp(3, 90);
      // Önerinin toplam süresini belirlemeye başlar
      final totalDays = ((data['total_days'] ??
              // Değer bulunmazsa varsayılan seçeneği kullanır
              data['totalDays'] ??
              // Değer bulunmazsa varsayılan seçeneği kullanır
              data['sure'] ??
              // Hedef gün alanını sayısal değere dönüştürür
              targetDays) as num)
          // Hesaplanan sayıyı tam sayıya çevirir
          .toInt()
          // Sayıyı izin verilen alt ve üst sınırlarda tutar
          .clamp(targetDays, 120);
      // Önerilen vazifeleri ID veya adlarıyla eşleştirir
      // AI önerisindeki vazife adları veya IDleri listesini alır
      final rawHabits =
          // Değer bulunmazsa varsayılan seçeneği kullanır
          data['target_habits'] ?? data['habit_names'] ?? data['habits'];
      // Eşleşen vazife IDlerini sırayla toplar
      final List<String> matchedIds = [];
      // Eşleşen vazife adlarını sırayla toplar
      final List<String> matchedNames = [];
      // Önerilen vazife alanı listeyse eşleştirmeye başlar
      if (rawHabits is List) {
        // Koleksiyondaki her öğeyi sırayla işler
        for (final item in rawHabits) {
          // name or ID bilgisini saklar
          final nameOrId = item.toString().toLowerCase().trim();
          // found bilgisini saklar
          final found = availableHabits.firstWhere(
            // Her vazifeyi önerideki ID ve adla karşılaştırır
            (h) =>
                // Önerilen kimlikle vazife IDsinin eşit olup olmadığını kontrol eder
                h.id.toLowerCase() == nameOrId ||
                // Önerilen metinde vazife adının geçip geçmediğini kontrol eder
                h.name.toLowerCase().contains(nameOrId) ||
                // Önerilen metinde vazife adının geçip geçmediğini kontrol eder
                nameOrId.contains(h.name.toLowerCase()),
            // Eşleşme bulunmazsa kullanılacak değeri belirler
            orElse: () => availableHabits.isNotEmpty
                // Koşul doğruysa kullanılacak sonucu belirler
                ? availableHabits.first
                // Koşul yanlışsa kullanılacak sonucu belirler
                : Habit(
                    // Kaydın benzersiz kimliğini belirler
                    id: '',
                    // Vazifenin veya kişiliğin adını belirler
                    name: '',
                    // Vazifenin veya önerinin açıklamasını belirler
                    description: '',
                    // Vazifenin zorluk derecesini belirler
                    difficulty: 1,
                    // Yeni kaydın oluşturulduğu zamanı alır
                    createdAt: DateTime(2026, 1, 1),
                    // Yeni vazifeyi henüz tamamlanan günü olmadan başlatır
                    completedDates: const []),
          );
          // Kullanılabilir veri varsa devam eder
          if (found.id.isNotEmpty && !matchedIds.contains(found.id)) {
            // Yeni öğeyi ilgili listeye veya kümeye ekler
            matchedIds.add(found.id);
            // Yeni öğeyi ilgili listeye veya kümeye ekler
            matchedNames.add(found.name);
          }
        }
      }
      // Eşleşme çıkmazsa mevcut ilk vazifeyi öneriye bağlar
      // Eşleşme çıkmazsa mevcut ilk vazifeyi öneriye bağlar
      if (matchedIds.isEmpty && availableHabits.isNotEmpty) {
        // Yeni öğeyi ilgili listeye veya kümeye ekler
        matchedIds.add(availableHabits.first.id);
        // Yeni öğeyi ilgili listeye veya kümeye ekler
        matchedNames.add(availableHabits.first.name);
      }
      // Yeni PactSuggestion nesnesi oluşturup döndürür
      return PactSuggestion(
        // başlık alanına baş ve sondaki boşlukları temizler
        title: title.trim(),
        // Vazifenin veya önerinin açıklamasını belirler
        description: description.trim(),
        // Ahdin bağlı olduğu vazife IDlerini aktarır
        habitIds: matchedIds,
        // vazife names alanına gelen değeri kullanır
        habitNames: matchedNames,
        // target days alanına gelen değeri kullanır
        targetDays: targetDays,
        // toplam days alanına gelen değeri kullanır
        totalDays: totalDays,
        // Önerinin gerekçesini aktarır
        rationale: rationale.trim(),
      );
    // İşlem başarısız olursa hata durumunu ele alır
    } catch (_) {
      // Geçerli bir sonuç bulunmadığında null döndürür
      return null;
    }
  }
  // Sohbette gösterilecek metinden ham JSON bloğunu çıkarır
  // Ham yanıttaki JSON öneri bloğunu sohbet metninden çıkarır
  static String cleanDisplayMessage(String raw) {
    // Hesaplanan değeri çağıran yere geri döndürür
    return raw
        // Ham mesajdaki JSON kod bloğunu boş metinle değiştirir
        .replaceAll(
            // reg exp bileşenini oluşturur
            RegExp(r'```(?:pact_suggestion|json)?\s*\{[\s\S]*?\}\s*```',
                // Aramada büyük küçük harf duyarlılığını belirler
                caseSensitive: false),
            // Gösterilecek veya kullanılacak metin parçasını ekler
            '')
        // Metnin başındaki ve sonundaki boşlukları siler
        .trim();
  }
}
